head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05011";
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.LD_MKT_TP_CD = '1';
scwin.NEWSEL = 4;
scwin.BZ_NEWPRE = 0;
scwin.CD_NEWPRE = '002';
scwin.SELECT = 2;
scwin.form = null;
scwin.nowPage = null;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.nowPage = '' + dma_page.get("currentPage") + '';
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05011.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_ElwSelectSub", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_ElwExcelDownload", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_ElwExcelUploadPop", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        $c.util.getComponent("dma_ElwMstReq").set("bzCd", scwin.BZ_NEWPRE);
        $c.util.getComponent("dma_ElwMstReq").set("listBzTpCd", scwin.CD_NEWPRE);
        $c.util.getComponent("dma_ElwMstReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        $("#ipt_checkAll").click(function() {
                if ($(this).is(":checked")) {
                    $("input:checkbox[name='checkSub']").attr("checked", true);
                } else {
                    $("input:checkbox[name='checkSub']").attr("checked", false);
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05011.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(elwpage vs elwpageupload) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05011.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["bzProcsNo"] != null && r["bzProcsNo"] !== '') { await scwin.elwDel(r["bzProcsNo"], r["listProcsStatCd"]); return; }
        await scwin.elwMst(r["isuCd"], r["bzProcsNo"], r["listProcsStatCd"], r["listProcsRsn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_ElwSelectSub_onclick
 * @description 「선택제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ElwSelectSub_onclick = function(e){
    try {
        fn_ElwSelectSub()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05011.btn_ElwSelectSub_onclick' }); }
};

/**
 * @method
 * @name btn_ElwExcelDownload_onclick
 * @description 「엑셀다운」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwExcelDownload_onclick = async function(e){
    try {
        await scwin.elwExcelDownload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05011.btn_ElwExcelDownload_onclick' }); }
};

/**
 * @method
 * @name btn_ElwExcelUploadPop_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwExcelUploadPop_onclick = async function(e){
    try {
        await scwin.elwExcelUploadPop()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05011.btn_ElwExcelUploadPop_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_90_onclick
 * @description krxpage_pagenavigator_90 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_90_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_ElwMstReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_90.page' }); } await scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ElwMst
 * @description Elw Mst 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwMst = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwMst",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ElwDel
 * @description Elw Del 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwDel = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwDel",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_ElwDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ElwExcelUploadPop
 * @description Elw Excel Upload Pop 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwExcelUploadPop = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelUploadPop",
        method: "post",
        action: "/list/elwPageUpload.do?method=elwExcelUploadPop",
        ref: "dma_ElwExcelUploadPopReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ElwExcelDownload
 * @description Elw Excel Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwExcelDownload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelDownload",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_ElwExcelDownloadReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elwMst
 * @description elw Mst 처리
 * @param {String} isuCd isuCd
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listProcsStatCd listProcsStatCd
 * @param {*} listProcsRsn listProcsRsn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwMst = async function (isuCd, bzProcsNo, listProcsStatCd, listProcsRsn) {
    if (bzProcsNo !== "") {
        $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.SELECT);
    } else {
        $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.NEWSEL);
    }
    fn_clearTransTbl();
    fn_setMainPage();
    $c.util.getComponent('dma_ElwMstReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_ElwMstReq').set('isFirst', 'N');
    if (listProcsStatCd === '03') {
        $c.util.getComponent('dma_ElwMstReq').set('listProcsStatCd', listProcsStatCd);
        $c.util.getComponent('dma_ElwMstReq').set('nowPage', listProcsRsn);
        $c.util.getComponent('dma_ElwMstReq').set('billLstSaveStatCd', '4');
        goNextPage(listProcsRsn);
    } else {
        scwin.form.action = '/list/elw.do';
        $c.util.getComponent('dma_ElwMstReq').set('method', 'searchElw');
        await scwin.tx_fn_ElwMst();
    }
};

/**
 * @method
 * @name elwDel
 * @description elw Del 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwDel = async function (bzProcsNo, listProcsStatCd) {
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    if (listProcsStatCd === '03') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!await scwin.confirmJob('D')) {
        return;
    }
    scwin.form.action = '/list/elwPage.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageDelete');
    await scwin.tx_fn_ElwDel();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elwPage.do', {});
};

/**
 * @method
 * @name elwExcelUploadPop
 * @description elw Excel Upload Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwExcelUploadPop = async function () {
    let i = 0;
    i++;
    const popName = "pop_excelUpload_" + i;
    if (scwin.getCookie(popName) !== popName) {
        $c.win.openPopup('', String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof popName !== 'undefined' ? popName : '') ? Object.assign({ scrollbars: false, resizable: true, width: "500", height: "500", type: "pageFramePopup" }, { id: (typeof popName !== 'undefined' ? popName : '') }) : { scrollbars: false, resizable: true, width: "500", height: "500", type: "pageFramePopup" }), {});
        (document.excelUploadForm || { elements: [] }).target = popName;
        (document.excelUploadForm || { elements: [] }).action = "/list/elwPageUpload.do?method=elwExcelUploadPop";
        (document.excelUploadForm || { elements: [] }).method = "post";
        await scwin.tx_fn_ElwExcelUploadPop();
    }
};

/**
 * @method
 * @name elwExcelDownload
 * @description elw Excel Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwExcelDownload = async function () {
    scwin.form.action = '/list/elwPage.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwExcelDownload');
    await scwin.tx_fn_ElwExcelDownload();
};

/**
 * @method
 * @name getCookie
 * @description get Cookie 처리
 * @param {*} Name Name
 * @returns {void}
 * @hidden N
 */
scwin.getCookie = function (Name) { const v = $c.util.getSessionStorage(Name); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};
